#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
public:
    bool isPythagoreanTree(int n, vector<vector<int>>& edges, int a, int b, int c) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto getDist = [&](int start, int target) -> int {
            vector<int> dist(n, -1);
            dist[start] = 0;
            queue<int> q;
            q.push(start);
            while (!q.empty()) {
                int curr = q.front(); q.pop();
                if (curr == target) return dist[curr];
                for (int nxt : adj[curr]) {
                    if (dist[nxt] == -1) {
                        dist[nxt] = dist[curr] + 1;
                        q.push(nxt);
                    }
                }
            }
            return -1;
        };
        vector<long long> sides = {getDist(a, b), getDist(b, c), getDist(a, c)};
        sort(sides.begin(), sides.end());
        if (sides[0] <= 0) return false;
        return sides[0] * sides[0] + sides[1] * sides[1] == sides[2] * sides[2];
    }
};

import java.util.*;

class Solution {
    public boolean isPythagoreanTree(int n, int[][] edges, int a, int b, int c) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        long d1 = getDist(a, b, n, adj);
        long d2 = getDist(b, c, n, adj);
        long d3 = getDist(a, c, n, adj);
        long[] sides = new long[]{d1, d2, d3};
        Arrays.sort(sides);
        if (sides[0] <= 0) return false;
        return sides[0] * sides[0] + sides[1] * sides[1] == sides[2] * sides[2];
    }

    private int getDist(int start, int target, int n, List<List<Integer>> adj) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        while (!q.isEmpty()) {
            int curr = q.poll();
            if (curr == target) return dist[curr];
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.offer(nxt);
                }
            }
        }
        return -1;
    }
}

var isPythagoreanTree = function(n, edges, a, b, c) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    function getDist(start, target) {
        const dist = new Array(n).fill(-1);
        dist[start] = 0;
        const q = [start];
        while (q.length > 0) {
            const curr = q.shift();
            if (curr === target) return dist[curr];
            for (const nxt of adj[curr]) {
                if (dist[nxt] === -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.push(nxt);
                }
            }
        }
        return -1;
    }
    const sides = [getDist(a, b), getDist(b, c), getDist(a, c)].sort((x, y) => x - y);
    if (sides[0] <= 0) return false;
    return sides[0] ** 2 + sides[1] ** 2 === sides[2] ** 2;
};
